            .cuMemcpyDtoH_v2 = lib.lookup(*const fn (*anyopaque, CUdeviceptr, usize) callconv(.C) CUresult, "cuMemcpyDtoH_v2") orelse return error.SymbolNotFound,
            .cuModuleLoadData = lib.lookup(*const fn (*CUmodule, *const anyopaque) callconv(.C) CUresult, "cuModuleLoadData") orelse return error.SymbolNotFound,
            .cuModuleGetFunction = lib.lookup(*const fn (*CUfunction, CUmodule, [*:0]const u8) callconv(.C) CUresult, "cuModuleGetFunction") orelse return error.SymbolNotFound,
            .cuLaunchKernel = lib.lookup(*const fn (CUfunction, u32, u32, u32, u32, u32, u32, u32, ?CUstream, ?[*] ?*anyopaque, ?[*] ?*anyopaque) callconv(.C) CUresult, "cuLaunchKernel") orelse return error.SymbolNotFound,
            .cuCtxSynchronize = lib.lookup(*const fn () callconv(.C) CUresult, "cuCtxSynchronize") orelse return error.SymbolNotFound,
        };
    }
};

pub const Tensor = struct {
    api: *const CudaAPI,
    data_host: []f32,
    data_device: CUdeviceptr,
    size: usize,

    pub fn init(allocator: std.mem.Allocator, api: *const CudaAPI, size: usize) !Tensor {
        const data_host = try allocator.alloc(f32, size);
        @memset(data_host, 0.0);
        var data_device: CUdeviceptr = 0;
        const res = api.cuMemAlloc_v2(&data_device, size * @sizeOf(f32));
        if (res != 0) return error.CudaAllocFailed;
        return Tensor{
            .api = api,
            .data_host = data_host,
            .data_device = data_device,
            .size = size,
        };
    }

    pub fn deinit(self: *Tensor, allocator: std.mem.Allocator) void {
        _ = self.api.cuMemFree_v2(self.data_device);
        allocator.free(self.data_host);
    }

    pub fn toDevice(self: *Tensor) !void {
        const res = self.api.cuMemcpyHtoD_v2(self.data_device, self.data_host.ptr, self.size * @sizeOf(f32));
        if (res != 0) return error.CudaMemcpyFailed;
    }

    pub fn toHost(self: *Tensor) !void {
        const res = self.api.cuMemcpyDtoH_v2(self.data_host.ptr, self.data_device, self.size * @sizeOf(f32));
        if (res != 0) return error.CudaMemcpyFailed;
    }
};

